// This cleans the AI's markdown formatting and turns the string into real JSON objects
const rawOutput = $input.item.json.output;
const cleanJson = rawOutput.replace(/```json|```/g, "").trim();
return JSON.parse(cleanJson);

// This node filters for shipments exactly 3 business days away
const today = new Date();
today.setHours(0, 0, 0, 0);

function addBusinessDays(date, days) {
  let result = new Date(date);
  let added = 0;
  while (added < days) {
    result.setDate(result.getDate() + 1);
    if (result.getDay() !== 0 && result.getDay() !== 6) { // 0=Sun, 6=Sat
      added++;
    }
  }
  return result;
}

const targetDate = addBusinessDays(today, 3);
const targetString = targetDate.toISOString().split('T')[0]; // YYYY-MM-DD

// Filter the incoming items from Google Sheets
return $input.all().filter(item => {
  const rawDate = item.json["Pickup Date"];

  // GUARD 1: Skip if the row is empty or doesn't have a date
  if (!rawDate || rawDate.toString().trim() === "") {
    return false;
  }

  const pickupDate = new Date(rawDate);

  // GUARD 2: Skip if the date format is corrupted/invalid
  if (isNaN(pickupDate.getTime())) {
    return false;
  }

  const pickupString = pickupDate.toISOString().split('T')[0];
  return pickupString === targetString;
});

/**
 * Optimized Reference Generator
 * Finds the highest IN number from the provided sheet rows.
 */

const recentRows = $input.all(); 
const currentShipment = $node["3-Business-Day Logic"].json;

let maxNumber = 0;

recentRows.forEach(item => {
  const row = item.json;
  // Look through every single cell in the row just in case
  for (let key in row) {
    const val = row[key];
    if (val && typeof val === 'string' && val.includes('IN')) {
      const match = val.match(/IN(\d+)-/);
      if (match) {
        const num = parseInt(match[1]);
        if (num > maxNumber) maxNumber = num;
      }
    }
  }
});

// If for some reason it still can't find it, we default to the last known 
// but this logic should now catch IN2627 easily.
const nextNumber = maxNumber > 0 ? maxNumber + 1 : 2628; 

const rawDate = currentShipment["Pickup Date"] || currentShipment["pickup_date"];
const pickupDate = new Date(rawDate);
const mm = String(pickupDate.getMonth() + 1).padStart(2, '0');
const dd = String(pickupDate.getDate()).padStart(2, '0');
const yyyy = pickupDate.getFullYear();

const newReference = `IN${String(nextNumber).padStart(4, '0')}-${mm}${dd}${yyyy}`;

return {
  ...currentShipment,
  new_client_reference: newReference,
  next_sequence_number: nextNumber
};

