// 1. Setup Carrier Contacts (Data remains static for precision)
const carriers = [
    { name: "{{CARRIER_A}}", email: "{{CARRIER_A_EMAIL}}" },
    { name: "{{CARRIER_B}}", email: "{{CARRIER_B_EMAILS}}" },
    { name: "{{CARRIER_C}}", email: "{{CARRIER_C_EMAILS}}" }
];

// 2. Capture the single incoming shipment (The truck)
const truck = $json;

// 3. Precise Field Extraction & Cleanup
// We ensure so_list is always a string and handle different possible key names
const cleanSOList = (truck.Shipment_Orders || truck.so_list || truck.Referencia || "").toString().trim();

// 4. Scalable Multiplexing with Safety Mapping
return carriers.map(carrier => {
    return {
        json: {
            // Keep all original metadata (Pickup Date, Row ID, etc.)
            ...truck, 

            // Explicit Carrier Assignments
            carrier_name: carrier.name,
            carrier_email: carrier.email,
            cc_email: "{{OPS_CONTACT_EMAIL}}",

            // Overwrite so_list with our cleaned version to prevent Agent errors
            so_list: cleanSOList,

            // Add a timestamp for auditability 
            processed_at: new Date().toISOString()
        }
    };
});

/**
 * This node parses the AI Agent's JSON string and merges it with 
 * the carrier metadata (emails/names) from the Multiplexer.
 * It also generates a summary item for the Notification node 
 * and a 'full_shipment_data' object to survive the Wait node.
 */

const results = [];
const inputItems = $input.all();

// 1. HARD-CODED EMAIL LOOKUP (Safety Net)
const emailLookup = {
  "{{CARRIER_A}}": "{{CARRIER_A_EMAIL}}",
  "{{CARRIER_B}}": "{{CARRIER_B_EMAILS}}",
  "{{CARRIER_C}}": "{{CARRIER_C_EMAILS}}"
};

// 2. ATTEMPT TO FIND MULTIPLEXER NODE DATA
let multiplexerItems = [];
const nodeNamesToTry = ["Code in JavaScript1", "Increment & Multiplex Logic", "Multiplexer", "Code in JavaScript3", "Code"];

for (const name of nodeNamesToTry) {
  try {
    multiplexerItems = $node[name].all();
    if (multiplexerItems.length > 0) break;
  } catch (e) {
    continue;
  }
}

// 3. PROCESS EACH AGENT OUTPUT
for (let i = 0; i < inputItems.length; i++) {
  const item = inputItems[i];
  let aiData = {};

  try {
    if (typeof item.json.output === 'string') {
      const cleanOutput = item.json.output.replace(/```json/g, "").replace(/```/g, "").trim();
      aiData = JSON.parse(cleanOutput);
    } else {
      aiData = item.json.output || {};
    }

    const multiplexerData = (multiplexerItems[i] && multiplexerItems[i].json) ? multiplexerItems[i].json : {};

    // 4. RESOLVE CARRIER NAME
    const carrierName = aiData.carrier_name || aiData.carrier_targeted || multiplexerData.carrier_name || "Unknown Carrier";
    const lookupKey = carrierName.toLowerCase().trim();

    // 5. ENHANCED DATE RESOLUTION
    let resolvedPickupDate = multiplexerData["Pickup Date"] || multiplexerData["pickup_date"] || multiplexerData["ETA"] || multiplexerData["Fecha"] || aiData.pickup_date || "";
    let resolvedDeliveryDate = multiplexerData["Delivery Date"] || multiplexerData["delivery_date"] || multiplexerData["Vence"] || multiplexerData["Factura"] || aiData.delivery_date || "";

    // Fallback Extraction Logic
    if (!resolvedPickupDate || !resolvedDeliveryDate) {
        const dateRegex = /(\d{1,2}\/\d{1,2}\/\d{4})/g;
        const textToScan = `${aiData.email_subject || ""} ${aiData.email_body || ""}`;
        const foundDates = textToScan.match(dateRegex) || [];

        // Use a Set to get unique date strings only
        const uniqueDates = [...new Set(foundDates)];

        if (!resolvedPickupDate && uniqueDates.length > 0) {
          resolvedPickupDate = uniqueDates[0];
        }

        // Only assign delivery date if we found a second, DIFFERENT date
        if (!resolvedDeliveryDate && uniqueDates.length > 1) {
          resolvedDeliveryDate = uniqueDates[1];
        }
    }

    // 6. FINAL DATA MERGE
    const baseOutput = {
        is_draftable: true, 
        email_subject: aiData.email_subject || `Re: ${multiplexerData.new_client_reference || "Shipment"}`,
        email_body: aiData.email_body || "Body generation failed.",
        loi_metadata: aiData.loi_metadata || {},
        carrier_email: aiData.carrier_email || multiplexerData.carrier_email || emailLookup[lookupKey] || "",
        cc_email: aiData.cc_email || multiplexerData.cc_email || "{{OPS_CONTACT_EMAIL}}",
        carrier_name: carrierName,
        new_client_reference: aiData.reference_id || multiplexerData.new_client_reference,
        pickup_date: resolvedPickupDate,
        delivery_date: resolvedDeliveryDate,
        row_number: multiplexerData.row_number || item.json.row_number,

        // --- DATA BUNDLE FOR THE SPREADSHEET ---
        full_shipment_data: {
          origin: multiplexerData["Origin"] || aiData.loi_metadata?.origin || "",
          destination: multiplexerData["Destination"] || aiData.loi_metadata?.destination || "",
          client: multiplexerData["Client"] || aiData.loi_metadata?.client || "{{END_CUSTOMER}}",
          so_list: multiplexerData["Shipment_Orders"] || aiData.loi_metadata?.orders || multiplexerData["so_list"] || "",
          pickup_date: resolvedPickupDate,
          delivery_date: resolvedDeliveryDate
        }
    };

    results.push({ json: baseOutput });

  } catch (error) {
    console.error(`Parsing Error on item ${i}:`, error.message);
    const fallback = (multiplexerItems[i] && multiplexerItems[i].json) ? multiplexerItems[i].json : {};
    results.push({ json: { ...fallback, error: "AI Parsing Failed" } });
  }
}

// 7. CREATE SUMMARY OBJECT (Prepend to list)
if (results.length > 0) {
  const summary = {
    json: {
      is_summary: true,
      is_draftable: false, 
      new_client_reference: results[0].json.new_client_reference,
      pickup_date: results[0].json.pickup_date,
      delivery_date: results[0].json.delivery_date,
      appended_pickup_date: [results[0].json.pickup_date], 
      appended_so_list: [results[0].json.full_shipment_data.so_list],
      carriers_count: results.length,
      full_shipment_data: results[0].json.full_shipment_data
    }
  };

  return [summary, ...results];
}

return results;
